(()=>{'use strict';
const E=x=>(window.esc?esc(x):String(x??'')),D=x=>(window.dateBR?dateBR(x):x),today=()=>new Date().toISOString().slice(0,10);
function nextLesson(){if(currentTab!=='Aulas'||document.querySelector('.sv5Lesson'))return;let ss=typeof sundays==='function'?sundays():[],next=ss.find(s=>s.date>=today()&&!state.lessonCancellations?.[s.date]);if(!next)return;const l=(state.lessons||{})[next.date]||{},box=document.createElement('section');box.className='sv5Lesson';box.innerHTML=`<div><span>Próxima aula</span><b>${D(next.date)}</b><small>${l.topic?E(l.topic):'Tema ainda não definido'}${l.teacher?' · '+E(l.teacher):''}</small></div><button data-sv5-open="${next.date}">Abrir planejamento</button>`;document.querySelector('#view .hero')?.insertAdjacentElement('afterend',box)}
function frequencySummary(){if(currentTab!=='Frequência'||document.querySelector('.sv5Freq'))return;const ss=(typeof sundays==='function'?sundays():[]).filter(s=>s.date<=today()&&!state.lessonCancellations?.[s.date]),last=ss.slice(-4),members=Array.isArray(state.members)?state.members:[];if(!last.length||!members.length)return;let vals=[];last.forEach(s=>{const a=state.attendance?.[s.date]||{};let marked=0,present=0;members.forEach(m=>{const v=a[m];if(v){marked++;if(v==='Presente')present++}});if(marked)vals.push(Math.round(present/marked*100))});const avg=vals.length?Math.round(vals.reduce((a,b)=>a+b,0)/vals.length):null,box=document.createElement('section');box.className='sv5Freq';box.innerHTML=`<span>Últimos domingos</span><b>${avg===null?'—':avg+'%'}</b><small>${avg===null?'Ainda não há registros suficientes.':'Média de presença entre os registros preenchidos.'}</small>`;document.querySelector('#view .hero')?.insertAdjacentElement('afterend',box)}
function run(){try{nextLesson();frequencySummary()}catch(e){console.warn('safe bundle v5 skipped',e)}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-sv5-open]');if(!b)return;const panel=document.getElementById('l-'+b.dataset.sv5Open);if(panel){panel.hidden=false;panel.scrollIntoView({behavior:'smooth',block:'start'})}});const old=window.renderTab;if(typeof old==='function')window.renderTab=function(){const r=old.apply(this,arguments);setTimeout(run,30);return r};document.addEventListener('DOMContentLoaded',()=>setTimeout(run,50));const s=document.createElement('style');s.textContent=`.sv5Lesson{display:flex;justify-content:space-between;align-items:center;gap:14px;background:var(--ios-card,#fff);border-radius:16px;padding:16px 18px;margin-bottom:14px}.sv5Lesson span,.sv5Lesson b,.sv5Lesson small,.sv5Freq span,.sv5Freq b,.sv5Freq small{display:block}.sv5Lesson span,.sv5Freq span{font-size:10px;text-transform:uppercase;letter-spacing:.055em;color:var(--teal);font-weight:750}.sv5Lesson b{font-size:18px;margin:2px 0}.sv5Lesson button{border:0;background:transparent;color:var(--teal);font-weight:700;white-space:nowrap;padding:10px}.sv5Freq{background:var(--ios-card,#fff);border-radius:16px;padding:16px 18px;margin-bottom:14px}.sv5Freq b{font-size:25px;color:var(--teal);letter-spacing:-.03em;margin:3px 0}@media(max-width:500px){.sv5Lesson{align-items:flex-start}.sv5Lesson button{padding:7px 0}}`;document.head.appendChild(s)})();